package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class CSVPrinter_printRecords_TriageGen1Test {

    private StringWriter out;
    private CSVPrinter csvPrinter;
    private ResultSet resultSet;
    private ResultSetMetaData metaData;

    @Before
    public void setUp() throws IOException {
        out = new StringWriter();
        csvPrinter = new CSVPrinter(out, CSVFormat.DEFAULT);
        resultSet = mock(ResultSet.class);
        metaData = mock(ResultSetMetaData.class);
    }

    @Test
    public void testPrintRecords_EmptyResultSet() throws SQLException, IOException {
        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);
        when(resultSet.next()).thenReturn(false);

        csvPrinter.printRecords(resultSet);

        assertEquals("", out.toString());
    }












}

package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class CSVPrinter_printRecords_TriageGen1Test {

    private StringWriter out;
    private CSVPrinter csvPrinter;
    private ResultSet resultSet;
    private ResultSetMetaData metaData;

    @Before
    public void setUp() throws IOException {
        out = new StringWriter();
        csvPrinter = new CSVPrinter(out, CSVFormat.DEFAULT);
        resultSet = mock(ResultSet.class);
        metaData = mock(ResultSetMetaData.class);
    }



    @Test
    public void testPrintRecords_SingleRowMultipleColumns() throws SQLException, IOException {
        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(3);

        // Simulate one row
        when(resultSet.next()).thenReturn(true, false);
        when(resultSet.getString(1)).thenReturn("val1");
        when(resultSet.getString(2)).thenReturn("val2");
        when(resultSet.getString(3)).thenReturn("val3");

        csvPrinter.printRecords(resultSet);

        // CSVFormat.DEFAULT uses comma as delimiter. 
        // The method uses print(getString) which doesn't add delimiters, 
        // then println() at the end of the row.
        // Based on the implementation: print("val1") -> print("val2") -> print("val3") -> println()
        // Result should be "val1val2val3" + line separator
        String expected = "val1val2val3" + System.lineSeparator();
        assertEquals(expected, out.toString());
    }










}

