import static org.mockito.Mockito.*;

public class CSVPrinter_printRecords_TriageGen1Test {

    private StringWriter out;
    private CSVPrinter csvPrinter;
    private ResultSet resultSet;
    private ResultSetMetaData metaData;

    @Before
    public void setUp() throws IOException {
        out = new StringWriter();
        csvPrinter = new CSVPrinter(out, CSVFormat.DEFAULT);
        resultSet = mock(ResultSet.class);
        metaData = mock(ResultSetMetaData.class);
    }













    @Test
    public void testPrintRecords_ZeroColumnCount() throws SQLException, IOException {
        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(0);
        when(resultSet.next()).thenReturn(true, false);

        csvPrinter.printRecords(resultSet);

        // Loop for columns won't execute, only println() executes per row
        assertEquals(System.lineSeparator(), out.toString());
    }
